//! 🎟️ The same Original Source retains every borrowed-output receiving phase and its consuming decoder ledger.
use super::*;
use semio_framework_job::{OriginalTurnFailure,StepContext};
use semio_framework_job_native_decode::{OriginalNativeDecodeSource,OriginalNativeDecodePolicy,OriginalNativeDecodeIssued,OriginalNativeDecodeOutcome};
pub type OriginalJsonOutputOutcome=OriginalNativeDecodeOutcome<RetainedCloneStep,OriginalReceivingPrimary>;
pub enum OriginalJsonOutputClose{Producer(Option<OriginalNativeDecodeOutcome<RetainedCloneStep>>),Source(RetainedCloneStep)}
/// 🧳️ Admission creates no parser or allocation before the containing native payload belongs to its actual Source.
pub struct OriginalJsonOutputSource<T:NativeReceive<DslValue>>{decode:OriginalNativeDecodeSource,receiver:Option<OriginalJsonOutputReceiving<T>>,limits:JsonReadLimits}
fn issued(turn:RetainedWorkOutcome<RetainedCloneStep,OriginalReceivingPrimary>,grant:RetainedCloneGrant)->OriginalNativeDecodeIssued<RetainedCloneStep,OriginalReceivingPrimary>{let progress=turn.result.as_ref().map(|step|step.progress()).unwrap_or_else(|error|error.progress);OriginalNativeDecodeIssued{value:turn.result,grant,progress,work:turn.work}}
impl<T:NativeReceive<DslValue>> OriginalJsonOutputSource<T>{
 pub const fn new(policy:OriginalNativeDecodePolicy,limits:JsonReadLimits)->Self{Self{decode:OriginalNativeDecodeSource::empty(policy),receiver:None,limits}}
 pub fn receive_step(&mut self,input:&[u8],cx:&mut StepContext<'_>)->Result<Option<OriginalJsonOutputOutcome>,OriginalTurnFailure>{let receiver=&mut self.receiver;let limits=self.limits;self.decode.receive_step(cx,|control,grant|{if let Some(receiver)=receiver.as_mut(){return issued(receiver.advance(input,control,grant.maximum_copy_bytes,grant),grant)}if !retained_clone_grant_admits(grant,OriginalJsonOutputReceiving::<T>::constructor_demand()){return issued(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0},grant)}match OriginalJsonOutputReceiving::admit(input,limits,control,grant){Ok((owner,progress))=>{*receiver=Some(owner);issued(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(progress)),work:1},grant)},Err(error)=>issued(RetainedWorkOutcome{result:Err(error.into()),work:0},grant)}})}
 pub fn take_step(&mut self,output:&mut Option<T>,cx:&mut StepContext<'_>)->Result<Option<OriginalJsonOutputOutcome>,OriginalTurnFailure>{let receiver=&mut self.receiver;self.decode.receive_step(cx,|_,grant|issued(match receiver.as_mut(){Some(receiver)=>{let turn=receiver.take_into(output,grant);RetainedWorkOutcome{result:turn.result.map_err(Into::into),work:turn.work}},None=>RetainedWorkOutcome{result:Err(invalid().into()),work:0}},grant))}
 pub fn ready(&self)->bool{self.receiver.as_ref().is_some_and(OriginalJsonOutputReceiving::ready)}
 pub fn receiver(&self)->Option<&OriginalJsonOutputReceiving<T>>{self.receiver.as_ref()}
 pub fn close_owned_step<U:semio_framework_value::retirement::RetireOwned>(&mut self,owner:&mut semio_framework_value::retirement::controlled::ControlledRetirement<U>,cx:&mut StepContext<'_>)->Result<Option<OriginalNativeDecodeOutcome<RetainedCloneStep>>,OriginalTurnFailure>{self.decode.close_producer_step(cx,|control,grant|{let mut work=0;let value=control.with_retirement(grant,|retirement|{let demand=owner.next_demand(grant.maximum_copy_bytes)?;if demand.capacity_bytes!=0{retirement.charge(demand.capacity_bytes)?}let value=owner.step(grant);work=owner.last_turn_work();value});let progress=value.as_ref().map(|step|step.progress()).unwrap_or_else(ValueError::retained_progress);OriginalNativeDecodeIssued{value,grant,progress,work}})}
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<OriginalJsonOutputClose,OriginalTurnFailure>{if let Some(receiver)=self.receiver.as_mut(){if !receiver.terminal_is_empty(){receiver.begin_close();return self.decode.close_producer_step(cx,|control,grant|{let mut work=0;let value=control.with_retirement(grant,|retirement|{let turn=receiver.close_step(retirement,grant);work=turn.work;turn.result});let progress=value.as_ref().map(|step|step.progress()).unwrap_or_else(ValueError::retained_progress);OriginalNativeDecodeIssued{value,grant,progress,work}}).map(OriginalJsonOutputClose::Producer)}}self.decode.close_step(cx).map(OriginalJsonOutputClose::Source)}
 pub fn terminal_is_empty(&self)->bool{self.decode.terminal_is_empty()&&self.receiver.as_ref().is_none_or(OriginalJsonOutputReceiving::terminal_is_empty)}
}
